pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, address newOwner) public {
        // 1. keep the domain wide: only assume caller != address(0) to avoid accidental black-hole, and newOwner != caller to make change observable
        vm.assume(caller != address(0));
        vm.assume(newOwner != address(0));
        vm.assume(caller != newOwner);
        // 2. set the initial owner to caller so that the rule "only owner changes owner" is testable
        vm.prank(caller);
        c.transferOwnership(caller);
        // record current owner
        address ownerBefore = c.owner();
        // 3. an arbitrary actor (the fuzzed `caller`) attempts transferOwnership
        vm.prank(caller);
        c.transferOwnership(newOwner);
        address ownerAfter = c.owner();
        // The reference satisfies: owner changes if and only if caller was the current owner (ownerBefore == caller).
        // The buggy version changes the owner regardless of caller.
        assertTrue((ownerAfter == newOwner) == (ownerBefore == caller));
    }
}

