pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address newOwner) public {
        vm.assume(newOwner != address(0));
        vm.assume(newOwner != address(this));
        // Deploy a re-entrant attacker that calls transferOwnership from its receive
        ReentrantAttacker attacker = new ReentrantAttacker(c);
        // Prank the current owner (address(this)) to set up the scenario
        vm.startPrank(address(this));
        c.transferOwnership(address(attacker));
        // Now attacker is owner; it will re-enter during transferOwnership call
        // Actually, we need to demonstrate the property: when the current owner calls transferOwnership(newOwner),
        // the new owner must be newOwner after the call. The buggy version allows re-entrancy from the attacker
        // to overwrite the stored owner mid-call. The reference version's onlyOwner modifier prevents this.
        // So we call transferOwnership as the owner (attacker), which triggers receive, which re-enters.
        vm.stopPrank();
        // Transfer ownership back to this contract to act as original owner
        vm.prank(address(attacker));
        c.transferOwnership(address(this));
        // Set up re-entrant attack: the attacker's receive() will call transferOwnership with a different address
        attacker.setTarget(address(uint160(address(this)) ^ 1)); // some arbitrary different address
        vm.prank(address(this));
        try c.transferOwnership(newOwner) {} catch {}
        // After the call, the owner should be newOwner if the call succeeded and no re-entrancy altered it.
        // The invariant: if the current owner calls transferOwnership(newOwner) and it doesn't revert,
        // the final owner must equal newOwner.
        assertTrue(c.owner() == newOwner);
    }
}

contract ReentrantAttacker {
    C public target;
    address public reentrantTarget;
    constructor(C _target) { target = _target; }
    function setTarget(address _reentrantTarget) external { reentrantTarget = _reentrantTarget; }
    receive() external payable {
        // Re-enter transferOwnership to overwrite owner
        if (reentrantTarget != address(0)) {
            target.transferOwnership(reentrantTarget);
        }
    }
}

